class Solution {
public:
    int numberOfBoomerangs(vector<vector<int>>& points) {
        int n = points.size();
        int ans = 0;
        for (int i = 0; i < n; i++) {
            unordered_map<long long, int> cnt;
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                long long dx = (long long)points[i][0] - points[j][0];
                long long dy = (long long)points[i][1] - points[j][1];
                long long d = dx * dx + dy * dy;
                cnt[d]++;
            }
            for (auto& p : cnt) {
                int c = p.second;
                ans += c * (c - 1);
            }
        }
        return ans;
    }
};
